// attr: allocate output holder the callee will fill (pointer + length)
MARIADB_CONST_STRING *attr = new MARIADB_CONST_STRING();
// Enforce field validity: must come from result metadata (tracked by owner attribute)
int from_metadata = FUZZ_GET_ATTR_INT(field, "from_metadata");
if (!from_metadata) { FUZZ_BAIL(); }
// Generate a valid enum mariadb_field_attr_t (0..1)
unsigned int t = *FUZZ_PARAM(unsigned int) % 2; // MARIADB_FIELD_ATTR_DATA_TYPE_NAME or _FORMAT_NAME
enum mariadb_field_attr_t type = (enum mariadb_field_attr_t)t;
// Invoke target
int rc = mariadb_field_attr(attr, field, type);
// Basic sanity: rc can be 0/!=0 depending on support; if failure, drop the object
if (rc != 0 && (attr->str == nullptr || attr->length == 0)) {
  delete attr; FUZZ_BAIL();
}
// Persist minimal provenance for downstream usage
FUZZ_SET_ATTR_INT(attr, "valid", 1);
// Provide attr as output

// name must be non-NULL; use random string
std::string s = FUZZ_PARAM_STR();
const char *name = s.c_str();
// type is library-defined; fuzzer explores space of ints
int type = (int)(*FUZZ_PARAM(unsigned int));
// mysql may be valid or NULL. We always have a non-NULL input; allow any connection state.
(void)mysql_client_find_plugin(mysql, name, type);
// No outputs; returned pointer (if any) is managed by the client library, not us

// Requires a valid, initialized connection handle
int connected = FUZZ_GET_ATTR_INT(mysql, "connected");
if (!connected) { FUZZ_BAIL(); }
// Restore default LOCAL INFILE handler
mysql_set_local_infile_default(mysql);
// Keep mysql alive as output

// mysql must be a valid MYSQL pointer
int initialized = FUZZ_GET_ATTR_INT(mysql, "initialized");
if (!initialized) { FUZZ_BAIL(); }
// Provide an SQLSTATE or NULL. Use either a 5-char code or nullptr with 50% chance
const char *sqlstate = nullptr;
if ((*FUZZ_PARAM(unsigned int) & 1u) != 0u) {
  static char state_buf[6];
  std::string st = FUZZ_PARAM_STR();
  // Ensure exactly 5 characters (pad/truncate), and NUL-terminate
  for (int i = 0; i < 5; ++i) state_buf[i] = (i < (int)st.size() ? st[i] : '0');
  state_buf[5] = '\0';
  sqlstate = state_buf;
}
// Use a format with one %s argument to avoid undefined varargs usage
std::string msg = FUZZ_PARAM_STR();
my_set_error(mysql, (unsigned int)(*FUZZ_PARAM(unsigned int)), sqlstate, "%s", msg.c_str());
// Keep mysql for downstream inspection

// Requires buffered result (mysql_store_result). Enforce via attribute
int is_buffered = FUZZ_GET_ATTR_INT(res, "buffered");
if (!is_buffered) { FUZZ_BAIL(); }
(void)mysql_num_rows(res);
// Keep result alive

// Any valid result
int valid = FUZZ_GET_ATTR_INT(res, "valid");
if (!valid) { FUZZ_BAIL(); }
(void)mysql_num_fields(res);
// Keep result alive

// Valid result, legacy EOF indicator
int valid = FUZZ_GET_ATTR_INT(res, "valid");
if (!valid) { FUZZ_BAIL(); }
(void)mysql_eof(res);
// Keep result alive

// Valid result with metadata
int valid = FUZZ_GET_ATTR_INT(res, "valid");
if (!valid) { FUZZ_BAIL(); }
unsigned int n = mysql_num_fields(res);
if (n == 0) { FUZZ_BAIL(); }
unsigned int idx = (unsigned int)(*FUZZ_PARAM(unsigned int) % n);
MYSQL_FIELD *f = mysql_fetch_field_direct(res, idx);
// If non-NULL, mark provenance for potential downstream attribute queries
if (f) { FUZZ_SET_ATTR_INT(f, "from_metadata", 1); }
// Keep result alive

int valid = FUZZ_GET_ATTR_INT(res, "valid");
if (!valid) { FUZZ_BAIL(); }
MYSQL_FIELD *arr = mysql_fetch_fields(res);
if (arr) {
  // Mark that returned fields originate from metadata
  unsigned int n = mysql_num_fields(res);
  for (unsigned int i = 0; i < n && i < 8u; ++i) { // cap small to keep runtime fast
    FUZZ_SET_ATTR_INT(&arr[i], "from_metadata", 1);
  }
}
// Keep result alive

// Only valid for buffered results
int is_buffered = FUZZ_GET_ATTR_INT(res, "buffered");
if (!is_buffered) { FUZZ_BAIL(); }
(void)mysql_row_tell(res);
// Keep result alive

int valid = FUZZ_GET_ATTR_INT(res, "valid");
if (!valid) { FUZZ_BAIL(); }
(void)mysql_field_tell(res);
// Keep result alive

// Valid MYSQL pointer with a recent/pending result; we just require initialization
int initialized = FUZZ_GET_ATTR_INT(mysql, "initialized");
if (!initialized) { FUZZ_BAIL(); }
(void)mysql_field_count(mysql);
// Keep mysql alive

int initialized = FUZZ_GET_ATTR_INT(mysql, "initialized");
if (!initialized) { FUZZ_BAIL(); }
(void)mysql_more_results(mysql);
// Keep mysql alive

// Advancing requires multi-result context; enforce via attribute
int can_next = FUZZ_GET_ATTR_INT(mysql, "can_next_result");
if (!can_next) { FUZZ_BAIL(); }
(void)mysql_next_result(mysql);
// Keep mysql alive

int initialized = FUZZ_GET_ATTR_INT(mysql, "initialized");
if (!initialized) { FUZZ_BAIL(); }
(void)mysql_affected_rows(mysql);
// Keep mysql alive

// Requires a connected session
int connected = FUZZ_GET_ATTR_INT(mysql, "connected");
if (!connected) { FUZZ_BAIL(); }
my_bool mode = (my_bool)((*FUZZ_PARAM(unsigned int)) & 1u);
(void)mysql_autocommit(mysql, mode);
// Keep mysql alive

// Commit requires a valid, connected MYSQL pointer
