import os
import random
import string
from typing import List

# Data type: filesystem path
# Goal: Produce interesting but valid-looking path strings for FUZZ_PARAM_FILENAME and FUZZ_PARAM_STR
# used by mysql_ssl_set and mysql_options4. The fuzzer treats the returned bytes as the content
# backing both FUZZ_PARAM_FILENAME and FUZZ_PARAM_STR selections. We'll pack multiple NUL-terminated
# strings into one buffer so the harness can slice them as needed.
#
# Strategy:
# - Generate a corpus of plausible filesystem paths and general strings (charset names, groups, etc.).
# - Include absolute/relative, with directories, extensions, hidden, spaces, unicode, dot-dirs.
# - Keep total size <= 4096 bytes.
# - Join entries with NUL separators and ensure final buffer ends with NUL.
# - Deterministic randomness based on provided seed.

SAFE_ASCII = string.ascii_letters + string.digits + "-_+."

UNICODE_SAMPLES = [
    "ä", "ö", "ü", "ß", "ñ", "ø", "å", "ç", "é", "í", "ł", "Ж", "Я", "漢字", "한글", "日本語",
]

# Common SSL-related file names and dirs
SSL_FILENAMES = [
    "client-key.pem", "client-cert.pem", "ca.pem", "ca-bundle.crt", "ca-certificates.crt",
    "tls.key", "tls.crt", "chain.pem", "dhparam.pem",
]

# Common directories where certs may exist
SSL_DIRS = [
    "/etc/ssl", "/etc/ssl/certs", "/etc/pki/tls/certs", "/usr/local/etc/ssl",
    "C:/ProgramData/ssl", "C:/ssl", "\\\x5c?\\C:\\ssl",  # raw-looking, still a string
]

# Charset names typical for MariaDB/MySQL
CHARSETS = [
    "utf8", "utf8mb4", "latin1", "ascii", "ucs2", "utf16", "utf32", "cp1251", "koi8r", "big5",
    "gbk", "sjis", "euckr", "tis620", "greek",
]

# Groups/sections from my.cnf
GROUPS = [
    "client", "mysql", "mysqld", "mysqld_safe", "mariadb", "client-mariadb",
]

# Cipher list examples (as a general string input); not necessarily validated by lib
CIPHERS = [
    "ECDHE-ECDSA-AES256-GCM-SHA384", "ECDHE-RSA-AES128-GCM-SHA256", "TLS_AES_256_GCM_SHA384",
    "TLS_AES_128_GCM_SHA256", ":@SECLEVEL=1",
]

# Bind addresses (used by MYSQL_OPT_BIND). Provide both IPs and hostnames.
BIND_STRINGS = [
    "0.0.0.0", "127.0.0.1", "::1", "localhost", "myhost.local", "192.168.1.100",
]

# Utility builders

def rand_choice(rng: random.Random, items: List[str]) -> str:
    return rng.choice(items)


def rand_name(rng: random.Random, min_len=3, max_len=12) -> str:
    n = rng.randint(min_len, max_len)
    s = ''.join(rng.choice(SAFE_ASCII) for _ in range(n))
    # Mix in occasional unicode
    if rng.random() < 0.3:
        s += rng.choice(UNICODE_SAMPLES)
    return s


def rand_ext(rng: random.Random) -> str:
    return rng.choice([".pem", ".crt", ".key", ".der", ".p12", ".cnf", ".cfg", ".ini", ".txt"]) 


def build_path_posix(rng: random.Random) -> str:
    parts = []
    depth = rng.randint(1, 4)
    for i in range(depth):
        choice = rng.random()
        if choice < 0.1:
            parts.append(".")
        elif choice < 0.2:
            parts.append("..")
        else:
            base = rand_name(rng)
            if rng.random() < 0.2:
                base = "." + base  # hidden
            parts.append(base)
    leaf = rand_choice(rng, SSL_FILENAMES) if rng.random() < 0.5 else rand_name(rng) + (rand_ext(rng) if rng.random() < 0.8 else "")
    return "/" + "/".join(parts + [leaf])


def build_path_windows(rng: random.Random) -> str:
    drive = rng.choice(["C:", "D:", "E:"])
    depth = rng.randint(1, 4)
    parts = []
    for _ in range(depth):
        base = rand_name(rng)
        if rng.random() < 0.2:
            base += " " + rand_name(rng, 2, 5)  # space in name
        parts.append(base)
    leaf = rand_choice(rng, SSL_FILENAMES) if rng.random() < 0.5 else rand_name(rng) + (rand_ext(rng) if rng.random() < 0.8 else "")
    return drive + "\\" + "\\".join(parts + [leaf])


def build_rel_path(rng: random.Random) -> str:
    depth = rng.randint(1, 3)
    parts = []
    for _ in range(depth):
        parts.append(rand_name(rng))
    leaf = rand_choice(rng, SSL_FILENAMES) if rng.random() < 0.5 else rand_name(rng) + (rand_ext(rng) if rng.random() < 0.8 else "")
    return os.path.join(*parts, leaf)


def build_dir_path(rng: random.Random) -> str:
    # ensure trailing separator in some cases
    if rng.random() < 0.5:
        base = rand_choice(rng, SSL_DIRS)
    else:
        base = build_path_posix(rng).rsplit('/', 1)[0]
    if base.endswith('/') or base.endswith('\\'):
        return base
    return base + ("/" if rng.random() < 0.7 else "\\")


def build_cipher_string(rng: random.Random) -> str:
    if rng.random() < 0.6:
        return rand_choice(rng, CIPHERS)
    # Constructed cipher suite list
    items = [rand_name(rng, 3, 6).upper() for _ in range(rng.randint(2, 5))]
    return ":".join(items)


def build_charset_name(rng: random.Random) -> str:
    if rng.random() < 0.7:
        return rand_choice(rng, CHARSETS)
    # variant with suffixes
    base = rand_choice(rng, CHARSETS)
    if rng.random() < 0.5:
        base += "_general_ci"
    return base


def build_group_name(rng: random.Random) -> str:
    if rng.random() < 0.7:
        return rand_choice(rng, GROUPS)
    return rand_name(rng)


def build_bind_string(rng: random.Random) -> str:
    if rng.random() < 0.7:
        return rand_choice(rng, BIND_STRINGS)
    return rand_name(rng) + ".local"


def make_entries(rng: random.Random) -> List[str]:
    entries: List[str] = []

    # For mysql_ssl_set: need filenames and a cipher string
    # Generate multiple candidates so the fuzzer can pick any
    for _ in range(6):
        entries.append(build_path_posix(rng))
    for _ in range(4):
        entries.append(build_path_windows(rng))
    for _ in range(4):
        entries.append(build_rel_path(rng))
    for _ in range(3):
        entries.append(build_dir_path(rng))
    for _ in range(4):
        entries.append(build_cipher_string(rng))

    # For mysql_options4 cases: file/group, charset/dir, bind/extra
    for _ in range(5):
        entries.append(build_charset_name(rng))
    for _ in range(5):
        entries.append(build_group_name(rng))
    for _ in range(5):
        entries.append(build_bind_string(rng))

    # Also include some config file-like paths and names
    for _ in range(5):
        entries.append(build_path_posix(rng).rsplit('/', 1)[0] + "/my.cnf")
        entries.append(build_path_windows(rng).rsplit('\\', 1)[0] + "\\my.ini")

    # Ensure a few very short and empty-like strings (but non-empty to avoid NULL pointers confusion)
    entries.extend([
        ".", "..", "/etc/my.cnf", "/etc/mysql/my.cnf", "C:/my.ini", "/tmp", "/var/tmp",
    ])

    # Deduplicate while preserving order
    seen = set()
    uniq: List[str] = []
    for e in entries:
        if e not in seen:
            seen.add(e)
            uniq.append(e)

    return uniq


def pack_nul_separated(strings: List[str], max_bytes: int = 4096) -> bytes:
    out = bytearray()
    for s in strings:
        b = s.encode('utf-8', errors='ignore') + b"\x00"
        if len(out) + len(b) > max_bytes:
            break
        out += b
    if not out or out[-1] != 0:
        out += b"\x00"
    return bytes(out)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Randomly shuffle constructed entries to vary ordering per seed
    entries = make_entries(rng)
    rng.shuffle(entries)

    # Bias: ensure first few entries match the immediate needs of mysql_ssl_set
    # key, cert, ca, capath, cipher: add explicit examples at the front
    prefix = [
        "/etc/ssl/private/client-key.pem",
        "/etc/ssl/certs/client-cert.pem",
        "/etc/ssl/certs/ca-certificates.crt",
        "/etc/ssl/certs/",
        "ECDHE-RSA-AES128-GCM-SHA256",
    ]
    # Prepend while preserving uniqueness
    prefix_unique = []
    seen = set()
    for p in prefix + entries:
        if p not in seen:
            prefix_unique.append(p)
            seen.add(p)

    # Pack into NUL-separated buffer
    buf = pack_nul_separated(prefix_unique, max_bytes=4096)
    return buf

import random
