import string
from typing import List

# Target data type: hostname (DNS name or IP literal). The fuzzer stubs call FUZZ_PARAM_STR
# for parameters: host, user, pass, db, unix_socket; and integers for port/clientflag (not our buffer).
# Our single generated bytes buffer will be fed to FUZZ_PARAM_STR/FUZZ_PARAM_FILENAME, so we
# craft a corpus element containing multiple newline-separated tokens so that different
# FUZZ_PARAM_STR calls can pull distinct, valid values by splitting. The first token should
# be a valid hostname/IP to exercise connection parameter parsing.
# We include:
#  - host: valid IPv4/IPv6/DNS
