#  - pass: plausible password
#  - db: plausible schema name
#  - sock path or named pipe name (for unix_socket on POSIX/Windows)
#  - extra variants: punycode-like, IPv6 zone index, bracketed IPv6, localhost aliases
# All tokens are ASCII and <= 4096 total.

DNS_LABEL_CHARS = string.ascii_lowercase + string.digits + "-"
USER_CHARS = string.ascii_letters + string.digits + "_-."
PASS_CHARS = string.ascii_letters + string.digits + string.punctuation
DB_CHARS = string.ascii_lowercase + string.digits + "_#$"


def _rand_ipv4(r: random.Random) -> str:
    return str(ipaddress.IPv4Address(r.getrandbits(32)))


def _rand_ipv6(r: random.Random) -> str:
    # Random IPv6, sometimes compressible, sometimes with zone id
    addr = ipaddress.IPv6Address(r.getrandbits(128))
    s = str(addr.compressed if r.random() < 0.7 else addr.exploded)
    if r.random() < 0.2:
        zone = r.choice(["eth0", "en0", "lo0"]) + str(r.randrange(0, 3))
        s = s + "%" + zone
    if r.random() < 0.3:
        s = f"[{s}]"  # URL-style bracketed literal
    return s


def _rand_dns_label(r: random.Random, min_len=1, max_len=20) -> str:
    ln = r.randint(min_len, max_len)
    # labels cannot start/end with '-', keep internal hyphens
    while True:
        label = ''.join(r.choice(DNS_LABEL_CHARS) for _ in range(ln))
        if label[0] == '-' or label[-1] == '-':
            continue
        return label


def _rand_dns_name(r: random.Random) -> str:
    # 1-5 labels, maybe with punycode-like prefix xn--
    nlabels = r.randint(1, 5)
    labels: List[str] = []
    for i in range(nlabels):
        if r.random() < 0.2:
            # simulate punycode label
            core = _rand_dns_label(r, 3, 12)
            labels.append("xn--" + core)
        else:
            labels.append(_rand_dns_label(r, 1, 20))
    name = '.'.join(labels)
    if r.random() < 0.15:
        name += '.'  # trailing dot (FQDN)
    return name


def _rand_username(r: random.Random) -> str:
    presets = [
        "root", "admin", "user", "maria", "mysql", "test", "readonly",
    ]
    if r.random() < 0.5:
        return r.choice(presets)
    ln = r.randint(1, 24)
    return ''.join(r.choice(USER_CHARS) for _ in range(ln))


def _rand_password(r: random.Random) -> str:
    presets = ["", "password", "secret", "toor", "P@ssw0rd!", "123456", "correcthorsebatterystaple"]
    if r.random() < 0.4:
        return r.choice(presets)
    ln = r.randint(0, 32)
    # Avoid embedded newlines (we use newline as token separator)
    choices = PASS_CHARS.replace('\n', '').replace('\r', '')
    return ''.join(r.choice(choices) for _ in range(ln))


def _rand_db_name(r: random.Random) -> str:
    presets = ["", "test", "mysql", "information_schema", "performance_schema", "sys"]
    if r.random() < 0.5:
        return r.choice(presets)
    ln = r.randint(1, 32)
    return ''.join(r.choice(DB_CHARS) for _ in range(ln))


def _rand_socket(r: random.Random) -> str:
    # Either a plausible UNIX socket path, Windows named pipe, or empty
    choice = r.random()
    if choice < 0.2:
        return ""  # empty means default
    if choice < 0.6:
        # UNIX-like path
        bases = ["/var/run/mysqld/mysqld.sock", "/tmp/mysql.sock", "/var/lib/mysql/mysql.sock"]
        if r.random() < 0.6:
            return r.choice(bases)
        # Custom path
        sub = ''.join(r.choice(string.ascii_lowercase + string.digits + "-_") for _ in range(r.randint(3, 12)))
        return f"/tmp/{sub}.sock"
    else:
        # Windows named pipe
        name = ''.join(r.choice(string.ascii_letters + string.digits) for _ in range(r.randint(4, 12)))
        return f"\\\\.\\pipe\\{name}"


def _rand_hostname(r: random.Random) -> str:
    # Weighted choice among common host representations
    p = r.random()
    if p < 0.2:
        return "localhost"
    if p < 0.35:
        return "127.0.0.1"
    if p < 0.45:
        return "::1"
    if p < 0.6:
        return _rand_ipv4(r)
    if p < 0.8:
        return _rand_ipv6(r)
    return _rand_dns_name(r)


def _rand_clientflag(r: random.Random) -> str:
    # Although FUZZ supplies clientflag via another mechanism, include commonly used flags as extra tokens
    # so they may be consumed as strings where applicable (e.g., options via FUZZ_PARAM_STR elsewhere).
    flags = [
        "CLIENT_FOUND_ROWS", "CLIENT_MULTI_STATEMENTS", "CLIENT_MULTI_RESULTS",
        "CLIENT_COMPRESS", "CLIENT_SSL", "CLIENT_PLUGIN_AUTH", "CLIENT_PROTOCOL_41"
    ]
    return r.choice(flags)


def _assemble_tokens(r: random.Random) -> List[str]:
    tokens: List[str] = []
    # Primary parameters expected by the stubs (order helps if the harness consumes sequentially):
    tokens.append(_rand_hostname(r))     # host
    tokens.append(_rand_username(r))     # user
    tokens.append(_rand_password(r))     # password
    tokens.append(_rand_db_name(r))      # db
    tokens.append(_rand_socket(r))       # unix_socket

    # Provide alternative/edge hostnames to diversify FUZZ_PARAM_STR calls beyond the first five.
    alt_hosts = [
        "localhost.localdomain",
        "[::1]",
        "::ffff:127.0.0.1",  # IPv4-mapped
        "xn--exmple-cua.com",  # punycode-like
        _rand_ipv4(r),
        _rand_ipv6(r),
        _rand_dns_name(r),
    ]
    tokens.extend(alt_hosts)

    # Additional plausible values that other option paths might use
    tokens.extend([
        _rand_clientflag(r),
        "utf8",
        "utf8mb4",
        "latin1",
        "socket",
        "tcp",
        "",
    ])

    # Ensure tokens do not contain embedded newlines
    clean_tokens = [t.replace('\n', ' ').replace('\r', ' ') for t in tokens]
    return clean_tokens


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    tokens = _assemble_tokens(r)
    # Join tokens with newlines so multiple FUZZ_PARAM_STR invocations can consume sequential values.
    data = "\n".join(tokens)
    b = data.encode('utf-8')
    # Enforce size limit
    return b[:4096]

import random
import string
from typing import List

# Generator for SQL query strings to exercise mysql_query and mysql_query_start fuzzers.
# Constraints from stubs:
# - FUZZ_PARAM_STR supplies the SQL string buffer.
# - Session is already connected by the harness.
# We should return bytes that represent a non-empty, NUL-terminated-capable SQL text when used via std::string.
# Focus on producing syntactically valid or near-valid SQL statements that cover diverse behaviors.

SQL_KEYWORDS = [
    "SELECT", "INSERT", "UPDATE", "DELETE", "REPLACE", "WITH", "CALL",
    "DO", "SET", "SHOW", "DESCRIBE", "EXPLAIN", "CREATE", "ALTER",
    "DROP", "TRUNCATE", "RENAME", "USE", "START TRANSACTION", "COMMIT",
    "ROLLBACK", "PREPARE", "EXECUTE", "DEALLOCATE PREPARE"
]

FUNC_EXPRS = [
    "NOW()", "CURRENT_TIMESTAMP", "RAND()", "UUID()", "VERSION()",
    "DATABASE()", "USER()", "CONNECTION_ID()", "SLEEP(0)", "MD5('a')",
]

TABLE_NAMES = [
    "t", "users", "orders", "`weird-name`", "`select`", "äö表", "𝖙𝖆𝖇𝖑𝖊"
]

DB_NAMES = ["test", "mysql", "information_schema", "performance_schema", "sys"]

COL_NAMES = [
    "id", "name", "value", "created_at", "updated_at", "`select`", "ä",
]

WHERE_PREDICATES = [
    "id = 1", "name IS NULL", "value > 0", "value BETWEEN 1 AND 2",
    "name LIKE 'a%'", "id IN (1,2,3)", "JSON_VALID(value)",
]

ENGINES = ["InnoDB", "MyISAM", "MEMORY", "CSV", "ARCHIVE"]

CHARSETS = ["utf8mb4", "latin1", "ucs2", "utf16", "utf32"]

COLLATIONS = [
    "utf8mb4_general_ci", "utf8mb4_0900_ai_ci", "latin1_swedish_ci",
]

def rnd(r: random.Random, seq: List[str]) -> str:
    return r.choice(seq)

def rand_ident(r: random.Random) -> str:
    # Occasionally return a quoted identifier to cover quoting paths
    choices = [
        lambda: ''.join(r.choices(string.ascii_letters + string.digits + "_", k=r.randint(1, 10))),
        lambda: f"`{''.join(r.choices(string.ascii_letters + string.digits + '_- ', k=r.randint(1, 8))).strip()}`",
    ]
    return r.choice(choices)()

def rand_string_literal(r: random.Random) -> str:
    # Generate a SQL string literal with proper quoting and some escapes
    # Use single quotes; double single-quotes to escape
    raw_choices = [
        "", "a", "abc", "O'Reilly", "line1\nline2", "😀", "二", "\\x00",
    ]
    if r.random() < 0.5:
        s = r.choice(raw_choices)
    else:
        length = r.randint(0, 20)
        alphabet = string.ascii_letters + string.digits + " _-:/.,@#\n\t"
        s = ''.join(r.choice(alphabet) for _ in range(length))
    s = s.replace("'", "''")
    return f"'{s}'"

def gen_select(r: random.Random) -> str:
    cols = []
    for _ in range(r.randint(1, 5)):
        choice = r.random()
        if choice < 0.2:
            cols.append("*")
        elif choice < 0.5:
            cols.append(rand_ident(r))
        elif choice < 0.8:
            cols.append(f"{rand_ident(r)} AS {rand_ident(r)}")
        else:
            cols.append(rnd(r, FUNC_EXPRS) + (" AS f" if r.random() < 0.5 else ""))
    table = rnd(r, TABLE_NAMES)
    sql = f"SELECT {', '.join(cols)} FROM {table}"
    if r.random() < 0.6:
        sql += " WHERE " + rnd(r, WHERE_PREDICATES)
    if r.random() < 0.4:
        sql += " ORDER BY " + rand_ident(r) + (" DESC" if r.random() < 0.5 else " ASC")
    if r.random() < 0.3:
        sql += f" LIMIT {r.randint(0, 5)} OFFSET {r.randint(0, 5)}"
    return sql

def gen_insert(r: random.Random) -> str:
    table = rnd(r, TABLE_NAMES)
    cols = ', '.join(rand_ident(r) for _ in range(r.randint(1, 4)))
    vals = ', '.join(
        [
            str(r.randint(-10, 10)) if r.random() < 0.5 else rand_string_literal(r)
            for _ in range(r.randint(1, 4))
        ]
    )
    sql = f"INSERT INTO {table} ({cols}) VALUES ({vals})"
    if r.random() < 0.3:
        sql += " ON DUPLICATE KEY UPDATE " + ', '.join(
            f"{rand_ident(r)}=VALUES({rand_ident(r)})" for _ in range(r.randint(1, 2))
        )
    return sql

def gen_update(r: random.Random) -> str:
    table = rnd(r, TABLE_NAMES)
    assigns = ', '.join(f"{rand_ident(r)} = " + (rand_string_literal(r) if r.random() < 0.5 else str(r.randint(0, 100))) for _ in range(r.randint(1, 3)))
    sql = f"UPDATE {table} SET {assigns}"
    if r.random() < 0.8:
        sql += " WHERE " + rnd(r, WHERE_PREDICATES)
    return sql

def gen_delete(r: random.Random) -> str:
    table = rnd(r, TABLE_NAMES)
    sql = f"DELETE FROM {table}"
    if r.random() < 0.9:
        sql += " WHERE " + rnd(r, WHERE_PREDICATES)
    return sql

def gen_ddl(r: random.Random) -> str:
    action = r.random()
    if action < 0.25:
        cols = ', '.join(f"{rand_ident(r)} INT" if r.random() < 0.6 else f"{rand_ident(r)} VARCHAR({r.randint(1,64)})" for _ in range(r.randint(1, 4)))
        extras = []
        if r.random() < 0.5:
            extras.append(f"ENGINE={rnd(r, ENGINES)}")
        if r.random() < 0.5:
            extras.append(f"DEFAULT CHARSET={rnd(r, CHARSETS)}")
        if r.random() < 0.3:
            extras.append(f"COLLATE {rnd(r, COLLATIONS)}")
        extras_sql = (" " + " ".join(extras)) if extras else ""
        return f"CREATE TABLE {rnd(r, TABLE_NAMES)} ({cols}){extras_sql}"
    elif action < 0.5:
        return f"ALTER TABLE {rnd(r, TABLE_NAMES)} ADD COLUMN {rand_ident(r)} INT"
    elif action < 0.75:
        return f"DROP TABLE IF EXISTS {rnd(r, TABLE_NAMES)}"
    else:
        return f"TRUNCATE TABLE {rnd(r, TABLE_NAMES)}"

def gen_misc(r: random.Random) -> str:
    choices = []
    choices.append(lambda: f"USE {rnd(r, DB_NAMES)}")
    choices.append(lambda: f"SET autocommit={r.choice([0,1])}")
    choices.append(lambda: "SHOW VARIABLES")
    choices.append(lambda: "SHOW STATUS")
    choices.append(lambda: f"EXPLAIN {gen_select(r)}")
    choices.append(lambda: "START TRANSACTION")
    choices.append(lambda: "COMMIT")
    choices.append(lambda: "ROLLBACK")
    return r.choice(choices)()

def gen_with_cte(r: random.Random) -> str:
    cte_name = rand_ident(r)
    cte = f"WITH {cte_name} AS ({gen_select(r)}) {gen_select(r).replace('FROM', f'FROM {cte_name},', 1)}"
    return cte

GENERATORS = [gen_select, gen_insert, gen_update, gen_delete, gen_ddl, gen_misc, gen_with_cte]

def assemble_multi(r: random.Random, parts: List[str]) -> str:
    # Join statements with semicolons to exercise multi-statement parsing when enabled
    return "; ".join(parts) + ";" if parts else parts

def generate(seed: int) -> bytes:
    r = random.Random(seed)

    # Decide how many statements to combine (1..3)
    count = 1 if r.random() < 0.6 else r.randint(2, 3)

    stmts = []
    for _ in range(count):
        gen = r.choice(GENERATORS)
        stmts.append(gen(r))

    sql = assemble_multi(r, stmts)

    # Ensure length constraints for buffer (<= 4096 bytes)
    # If too long, truncate at a statement boundary (last semicolon) else hard cut
    encoded = sql.encode('utf-8', errors='strict')
    if len(encoded) > 4096:
        cut = sql.rfind(';', 0, 4000)
        if cut == -1:
            sql = sql[:4000]
        else:
            sql = sql[:cut+1]
        encoded = sql.encode('utf-8', errors='strict')

    # Ensure non-empty; if empty by any chance, fall back to a simple select
    if not encoded:
        sql = "SELECT 1;"
        encoded = sql.encode('utf-8')

    return encoded
